<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Secretaria');
$pesquisa = trim($_GET['q'] ?? '');
$parametro = '%' . $pesquisa . '%';
$stmt = $conexao->prepare('SELECT q.id_questionario, q.titulo, q.descricao, q.data_criacao, u.nome AS criador FROM questionario q JOIN usuario u ON u.id_usuario=q.criado_por WHERE q.titulo LIKE ? ORDER BY q.data_criacao DESC');
$stmt->bind_param('s', $parametro); $stmt->execute(); $result=$stmt->get_result(); $questionarios=[]; while($row=$result->fetch_assoc()){$questionarios[]=$row;} $stmt->close();
?>
